// Generates supabase/seed.sql from lib/seed.ts and lib/scenarios.ts, so the database and the tests
// always use the same reference data. Run: npx tsx scripts/gen-seed.ts
import { writeFileSync } from "node:fs";
import { TEST_REGISTRY } from "../lib/scenarios";
import { BLOCKLIST_SEED, VENDOR_MASTER_SEED } from "../lib/seed";

const q = (v: string | undefined | null) => (v == null ? "null" : `'${String(v).replace(/'/g, "''")}'`);

const lines = [
  "-- Generated by scripts/gen-seed.ts. All data is synthetic.",
  "-- Resets demo data: clears runs/submissions and restores the reference tables.",
  "truncate submissions, documents, runs, run_events, check_results, reviewer_actions, messages restart identity cascade;",
  "truncate vendor_master, blocklist, test_registry cascade;",
  "",
  "insert into vendor_master (id, legal_name, pan, gstin, bank_account_hash, bank_last4) values",
  VENDOR_MASTER_SEED.map((v) => `  (${q(v.id)}, ${q(v.legal_name)}, ${q(v.pan)}, ${q(v.gstin)}, ${q(v.bank_account_hash)}, ${q(v.bank_last4)})`).join(",\n") + ";",
  "",
  "insert into blocklist (name, pan, bank_account_hash, reason) values",
  BLOCKLIST_SEED.map((b) => `  (${q(b.name)}, ${q(b.pan)}, ${q(b.bank_account_hash)}, ${q(b.reason)})`).join(",\n") + ";",
  "",
  "insert into test_registry (gstin, status, legal_name) values",
  Object.entries(TEST_REGISTRY).map(([g, e]) => `  (${q(g)}, ${q(e.status)}, ${q(e.legal_name)})`).join(",\n") + ";",
  "",
];
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log("wrote supabase/seed.sql");
